def get_grade(prompt):
    """Get a grade from user input."""
    while True:
        try:
            grade = float(input(prompt))
            if grade >= 0 and grade <= 100:
                return grade
            else:
                print("Grade must be between 0 and 100. Please try again.")
        except ValueError:
            print("That's not a valid grade. Please try again.")

def calculate_average(grades):
    """Calculate the average of a list of grades."""
    return sum(grades) / len(grades)

def main():
    student_name = input("Please enter the student's name: ")

    grades = []
    for i in range(1, 6):
        prompt = f"Please enter the student's grade in subject {i}: "
        grades.append(get_grade(prompt))

    average_grade = calculate_average(grades)

    if average_grade >= 90:
        message = f"{student_name}, your average grade is {average_grade} and you have passed!"
    else:
        message = f"{student_name}, your average grade is {average_grade} and you have failed!"

    print(message)

if __name__ == "__main__":
    main()
```
This program defines three functions: `get_grade`, which gets a grade from user input, `calculate_average`, which calculates the average of a list of grades, and `main`, which gets the student's name and grades, calculates the average, and prints out the appropriate message. The program then calls `main()` to run the program.

You can modify the `for` loop to get more or fewer grades depending on your needs.
